const DICTS: Record<UiLang, Dict> = { es, en, pt, it, de, fr };

/** Todos los textos de la interfaz en un idioma (los usa el buscador). */
export function uiEntries(lang: UiLang): Array<[UiKey, string]> {
  return (Object.keys(es) as UiKey[]).map((k) => [k, DICTS[lang][k] ?? es[k]]);
}

/**
 * Un texto con cantidad: si hay uno solo y existe la clave `<clave>One` («1 aviso»), esa; si no, la de
 * siempre («{n} avisos»). Así ninguna cantidad dice «1 avisos».
 */
export function plural(t: (key: UiKey, vars?: Record<string, string | number>) => string, key: UiKey, n: number, vars: Record<string, string | number> = {}): string {
  const one = `${key}One`;
  return n === 1 && Object.hasOwn(es, one) ? t(one as UiKey, { ...vars, n }) : t(key, { ...vars, n });
}

export function translate(lang: UiLang, key: UiKey, vars: Record<string, string | number> = {}): string {
  const s = DICTS[lang][key] ?? es[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m));
}

export function useT(): (key: UiKey, vars?: Record<string, string | number>) => string {
  const lang = useStore((s) => s.uiLang);
  return (key, vars) => translate(lang, key, vars);
}

/** Nombre legible de un tipo de sección/página. */
export function sectionName(t: (k: UiKey) => string, type: string): string {
  // Las páginas de una plantilla son de su propio tipo (`tpl:<id>`): se llaman como la plantilla.
  if (type.startsWith('tpl:')) {
    const tp = useStore.getState().design?.pageTemplates.find((x) => `tpl:${x.id}` === type);
    return tp?.title || t('sec.pageTemplate');
  }
  const key = `sec.${type}` as UiKey;
  const v = t(key);
  return v === key ? type : v;
}

/** Texto de la interfaz para una clave armada en tiempo de ejecución, con respaldo si no existe. */
export function uiText(t: (k: UiKey) => string, key: string, fallback: string): string {
  const v = t(key as UiKey);
  return v === key ? fallback : v;
}

/** Título de una página para el navegador: el núcleo da títulos fijos en español para las secciones. */
export function pageTitle(t: (k: UiKey) => string, p: { type: string; title: string; group: string }): string {
  const dynamic = p.type === 'custom' || p.type.startsWith('tpl:') || p.type === 'weekLeft' || p.type === 'weekRight' || p.type === 'daily' || p.group.startsWith('month:');
  return dynamic && p.title ? p.title : sectionName(t, p.type);
}

export const UI_LANGS: readonly UiLang[] = LANGUAGES;
export const UI_LANG_NAMES: Record<UiLang, string> = { es: 'Español', en: 'English', pt: 'Português', it: 'Italiano', de: 'Deutsch', fr: 'Français' };

export function isUiLang(l: string): l is UiLang {
  return (UI_LANGS as readonly string[]).includes(l);
}
